      currentWake: $("#current-wake"),
      lastWake: $("#last-wake"),
      lastWakeRelative: $("#last-wake-relative"),
      nextWakeTime: $("#next-wake-time"),
      nextWakeLocal: $("#next-wake-local"),
      nextWakeRelative: $("#next-wake-relative"),
